using System;using System.IO;using UnityEngine;using UnityEditor;using UnityEngine.Rendering;
public static class Glass114Review {
 public static void Compare(Camera camera,GameObject old,string output,Action draw){old.SetActive(false);foreach(var stage in new[]{"probe-off","probe-on"}){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Imported114-valid/small-obsidian.prefab");if(!prefab)throw new Exception("Formal obsidian Prefab missing");var o=(GameObject)PrefabUtility.InstantiatePrefab(prefab);o.transform.position=old.transform.position-Vector3.up*.05f;var r=o.GetComponent<Renderer>();var m=UnityEngine.Object.Instantiate(r.sharedMaterial);r.sharedMaterial=m;if(stage=="probe-off"){r.reflectionProbeUsage=ReflectionProbeUsage.Off;m.SetFloat("_EnvironmentReflections",0);m.EnableKeyword("_ENVIRONMENTREFLECTIONS_OFF");}Capture(camera,output,stage,draw);UnityEngine.Object.DestroyImmediate(o);UnityEngine.Object.DestroyImmediate(m);}old.SetActive(true);File.WriteAllText(Path.Combine(output,"formal-prefab.json"),"{\"pass\":true,\"formalImporter\":true,\"onlyReflectionReceptionToggled\":true,\"sameCameraLightGeometryColour\":true,\"playerExecuted\":false}");}
 static void Capture(Camera camera,string output,string name,Action draw){ShaderUtil.allowAsyncCompilation=false;var rt=new RenderTexture(1600,900,24,RenderTextureFormat.ARGB32,RenderTextureReadWrite.sRGB);camera.targetTexture=rt;for(int k=0;k<4;k++){draw();camera.Render();}var previous=RenderTexture.active;RenderTexture.active=rt;var image=new Texture2D(1600,900,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1600,900),0,0);image.Apply();File.WriteAllBytes(Path.Combine(output,name+".png"),image.EncodeToPNG());RenderTexture.active=previous;camera.targetTexture=null;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(image);}
}
